 private void ok(boolean value,String label){if(!value)throw new AssertionError(label);passed++;android.util.Log.i("HU_DIAGNOSTICS","PASS "+label);}
 private void waitFor(Callable<Boolean> ready)throws Exception{long end=SystemClock.elapsedRealtime()+10000;while(!ready.call()){if(SystemClock.elapsedRealtime()>end)throw new AssertionError("Fixture timed out");Thread.sleep(80);}}
 private void clearQueue(){new android.util.AtomicFile(new File(c.getFilesDir(),"diagnostics-pending-v1.json")).delete();}
 private JSONArray privateRows()throws Exception{return new JSONObject(new String(new android.util.AtomicFile(new File(c.getFilesDir(),"diagnostics-pending-v1.json")).readFully(),"UTF-8")).getJSONArray("reports");}
 private JSONArray summary()throws Exception{return new JSONArray(DiagnosticsQueue.summary(c).getString("reports"));}
 private String state()throws Exception{return summary().getJSONObject(0).getString("status");}
 private String body()throws Exception{return DiagnosticReport.preview(c,"other");}
 private static Map<String,String> unzip(InputStream source)throws Exception{Map<String,String> result=new HashMap<>();try(ZipInputStream in=new ZipInputStream(source)){ZipEntry e;byte[] buf=new byte[8192];while((e=in.getNextEntry())!=null){ByteArrayOutputStream bytes=new ByteArrayOutputStream();int n;while((n=in.read(buf))!=-1)bytes.write(buf,0,n);result.put(e.getName(),bytes.toString("UTF-8"));}}return result;}
 private Bundle export(String body)throws Exception{Bundle args=new Bundle();args.putString("body",body);return DiagnosticReport.create(c,args);}
 private Map<String,String> read(Bundle report)throws Exception{return unzip(c.getContentResolver().openInputStream(Uri.parse(report.getString("uri"))));}
 private String external(Uri uri,boolean grant)throws Exception{String id=UUID.randomUUID().toString();runOnMainSync(()->harness.open(uri,id,grant));long end=SystemClock.elapsedRealtime()+10000;while(SystemClock.elapsedRealtime()<end){try(Cursor r=c.getContentResolver().query(Uri.parse("content://hu.diagnostics.reader.results/"+id),null,null,null,null)){if(r!=null && r.moveToFirst() && !r.getString(0).isEmpty()){Thread.sleep(200);return r.getString(0);}}Thread.sleep(100);}throw new AssertionError("Recipient timed out");}
 private void rejected(JSONObject r,String label)throws Exception{boolean bad=false;try{DiagnosticSchema.report(r.toString());}catch(JSONException expected){bad=true;}ok(bad,label);}
 public void onCreate(Bundle args){phase=args==null?"all":args.getString("phase","all");start();}
