  clearQueue();key=DiagnosticsQueue.approve(c,body,true);fake=new FakeDiagnosticTransport();fake.loseFirst=true;DiagnosticsQueue.process(c,fake);DiagnosticsQueue.cancel(c,key);DiagnosticsQueue.process(c,fake,DiagnosticsQueue.next(c)+1);ok(state().equals("cancel_uncertain") && fake.posts==1,"ambiguous acceptance cancellation never invents server confirmation or reposts");
