 private TextView text(View root,String wanted){if(root instanceof TextView && wanted.equals(((TextView)root).getText().toString()))return (TextView)root;if(root instanceof ViewGroup){ViewGroup group=(ViewGroup)root;for(int i=0;i<group.getChildCount();i++){TextView found=text(group.getChildAt(i),wanted);if(found!=null)return found;}}return null;}
 private TextView view(Activity a,String wanted){if(Looper.myLooper()==Looper.getMainLooper())return text(a.getWindow().getDecorView(),wanted);AtomicReference<TextView> ref=new AtomicReference<>();runOnMainSync(()->ref.set(text(a.getWindow().getDecorView(),wanted)));return ref.get();}
 private void clickDialog(String wanted)throws Exception{waitFor(()->{List<AccessibilityNodeInfo> roots=new ArrayList<>();AccessibilityNodeInfo active=getUiAutomation().getRootInActiveWindow();if(active!=null)roots.add(active);for(android.view.accessibility.AccessibilityWindowInfo window:getUiAutomation().getWindows()){AccessibilityNodeInfo root=window.getRoot();if(root!=null)roots.add(root);}for(AccessibilityNodeInfo root:roots)for(AccessibilityNodeInfo node:root.findAccessibilityNodeInfosByText(wanted)){if(node.getText()!=null && wanted.equalsIgnoreCase(node.getText().toString()) && node.isEnabled())return node.performAction(AccessibilityNodeInfo.ACTION_CLICK);}return false;});}
